def encode_amount(dollars: str) -> str:
    negative = dollars.startswith('-')
    abs_dollars = dollars.lstrip('-')

    if '.' in abs_dollars:
        int_part, dec_part = abs_dollars.split('.')
    else:
        int_part = abs_dollars
        dec_part = '00'

    dec_part = (dec_part + '00')[:2]
    cents = int(int_part) * 100 + int(dec_part)

    if negative:
        cents = -cents

    return str(cents)

